python3 << 'PYEOF'
import pandas as pd, numpy as np

df = pd.read_csv('/app/benchmark/data.csv')

# Generate scatter data for price-rating
scatter_data = df[['Price','User Rating','Genre']].to_dict('records')

# Build scatter points with jitter for overlapping
import json

# yearly data for charts
yearly = df.groupby('Year').agg(
    avg_price=('Price','mean'),
    avg_rating=('User Rating','mean'),
    avg_reviews=('Reviews','mean'),
).round(3).reset_index()

yg = df.groupby(['Year','Genre']).agg(
    avg_price=('Price','mean'),
    avg_rating=('User Rating','mean'),
    avg_reviews=('Reviews','mean'),
    count=('Name','count'),
).round(3).reset_index()

fic_yearly = yg[yg['Genre']=='Fiction'].reset_index(drop=True)
nf_yearly = yg[yg['Genre']=='Non Fiction'].reset_index(drop=True)

years = list(range(2009,2020))

# segments
def seg(p):
    if p<=5: return '$0-5'
    if p<=10: return '$6-10'
    if p<=15: return '$11-15'
    if p<=20: return '$16-20'
    if p<=30: return '$21-30'
    return '$31+'
df['Segment'] = df['Price'].apply(seg)
seg_stats = df.groupby('Segment').agg(
    count=('Name','count'),
    avg_rating=('User Rating','mean'),
).round(3).reindex(['$0-5','$6-10','$11-15','$16-20','$21-30','$31+']).reset_index()

# Top authors
top_authors = df.groupby('Author').agg(
    appearances=('Name','count'),
    unique_books=('Name','nunique'),
    avg_price=('Price','mean'),
    avg_rating=('User Rating','mean'),
    avg_reviews=('Reviews','mean'),
).round(2).sort_values('appearances', ascending=False).head(10).reset_index()

fic = df[df['Genre']=='Fiction']
nfic = df[df['Genre']=='Non Fiction']

# Prepare JS data
chart_data = {
    'years': years,
    'yearly_price': [round(yearly[yearly['Year']==y]['avg_price'].values[0],2) for y in years],
    'yearly_rating': [round(yearly[yearly['Year']==y]['avg_rating'].values[0],3) for y in years],
    'yearly_reviews': [int(yearly[yearly['Year']==y]['avg_reviews'].values[0]) for y in years],
    'fic_price': [round(fic_yearly[fic_yearly['Year']==y]['avg_price'].values[0],2) for y in years],
    'nf_price': [round(nf_yearly[nf_yearly['Year']==y]['avg_price'].values[0],2) for y in years],
    'fic_rating': [round(fic_yearly[fic_yearly['Year']==y]['avg_rating'].values[0],3) for y in years],
    'nf_rating': [round(nf_yearly[nf_yearly['Year']==y]['avg_rating'].values[0],3) for y in years],
    'fic_count': [int(fic_yearly[fic_yearly['Year']==y]['count'].values[0]) for y in years],
    'nf_count': [int(nf_yearly[nf_yearly['Year']==y]['count'].values[0]) for y in years],
    'segments': seg_stats['Segment'].tolist(),
    'seg_counts': seg_stats['count'].astype(int).tolist(),
    'seg_ratings': seg_stats['avg_rating'].tolist(),
    'scatter': [{'x':r['Price'],'y':r['User Rating'],'g':r['Genre']} for r in scatter_data],
}

# Top authors HTML rows
auth_rows = ""
for _, a in top_authors.iterrows():
    auth_rows += f"""<tr>
        <td>{a['Author']}</td>
        <td style="text-align:center">{int(a['appearances'])}</td>
        <td style="text-align:center">{int(a['unique_books'])}</td>
        <td style="text-align:center">${a['avg_price']:.2f}</td>
        <td style="text-align:center">{a['avg_rating']:.2f}</td>
        <td style="text-align:center">{int(a['avg_reviews']):,}</td>
    </tr>"""

